40:   const nextZoom = clamp(cam.zoom * factor, MIN_ZOOM, MAX_ZOOM);
41:   const worldX = cam.x + cursorOffsetX / cam.zoom;
42:   const worldY = cam.y + cursorOffsetY / cam.zoom;
43:   return createCamera({
