// DOCUMENTS: the network — the wiring that lets two-number mini-IP
// addressable components exchange messages. Today it carries slim HTTP
// requests to a registered server; later stages attach more components
// without changing the send/enqueue contract. Stage 6 adds one additive
// hook: a gateway (the Router) takes a frame whose sender and target name
// different subnets, while same-subnet sends keep the exact contract below.
//
// CHECKS: every address crossing the wire is validated as a two-number
// mini-IP (<net>.<host>), and sends to unregistered hosts fail loud — with
// a gateway attached that still holds inside the subnet, and cross-subnet
// frames without a gateway throw the same "no server at <addr>" error.
const MINI_IP = /^\d+\.\d+$/;

export function createNetwork() {
  const servers = new Map();
  let gateway = null;

  function validate(addr) {
    if (!MINI_IP.test(addr)) {
      throw new Error(`network: invalid mini-IP address ${addr}`);
    }
  }

  function resolve(address) {
    validate(address);
    const server = servers.get(address);
    if (!server) {
      throw new Error(`network: no server at ${address}`);
    }
    return server;
  }

  // A frame is cross-subnet when sender and target name different network
  // numbers (10.2 -> 20.1); the gateway — the Router — owns those hops.
  function isCrossSubnet(from, to) {
    return String(from).split('.')[0] !== String(to).split('.')[0];
  }

  return {
    registerServer(address, server) {
      validate(address);
      servers.set(address, server);
    },

    // CHECKS: attachGateway accepts only an object exposing both forward
    // hooks, so a mis-wired gateway fails at boot instead of mid-trace.
    attachGateway(g) {
      if (!g || typeof g.forward !== 'function' || typeof g.forwardToQueue !== 'function') {
        throw new Error('network: gateway must expose forward and forwardToQueue');
      }
      gateway = g;
    },

    resolve,

    send({ from, to, request }) {
      validate(from);
      if (gateway && isCrossSubnet(from, to)) {
        return gateway.forward({ from, to, request });
      }
      const server = resolve(to);
      const response = server.handleRequest(request);
      return { from, to, request, response };
    },

    // `isYou` rides through untouched: the engine marks the learner's own
    // interactive-browser request, the server stores it on the queue row.
    deliverToQueue({ id, from, to, request, atTick, isYou = false }) {
      validate(from);
      if (gateway && isCrossSubnet(from, to)) {
        gateway.forwardToQueue({ id, from, to, request, atTick, isYou });
        return;
      }
      const server = resolve(to);
      server.enqueue({ id, from, to, request, atTick, isYou });
    },
  };
}

