// DOCUMENTS: the single-request hop-by-hop state machine behind the panel's
// "Step 1 Hop ->" trace — one hop per call, running across the same
// network/LB/queue/cache machinery the crowd uses (it does not fake a
// shortcut). 4 hops in Stage 1 (emit, route, serve, render); 5 in Stage 2
// (the LB's round-robin pick becomes its own hop); 6 in Stage 3 (the
// backend's cache-aside lookup and the HTTP response emission split into
// two hops so the learner can watch Cache 10.20 answer, then the backend
// emit); 7 in Stage 4 (the Database hop inserted after the cache check —
// the WRITE to Primary 10.30, the fresh or stale SELECT from Replica
// 10.31, or the SKIP a warm cache HIT earns).
//
// Stage 6 branches on host syntax: a path that carries a host
// (`example.com/about`, split on the first `/`) walks 10 hops — the browser
// asks DNS 10.60, the resolver answers from its tick-TTL ledger or its
// authoritative table, then the Stage 5 chain runs against the resolved
// target — while a host-less path (`/about`) replays the Stage 5 8-hop
// story hop-for-hop. A resolver NX answer ends the run after 3 hops: ask,
// NX answer, and the browser rendering the NX card — no GET is emitted.
//
// The machine owns the trace state and hop transitions; the engine owns
// the clock, the served-exchange record, and browser delivery, handed in
// as the callbacks below.
//
// CHECKS: an out-of-range stage fails loud at construction instead of
// building a trace that can never advance.
export function createTraceMachine({
  stage,
  serverAddress,
  servers,
  lb = null,
  network,
  cache = null,
  database = null,
  workerQueue = null,
  dns = null,
  bumpTick,
  getTick,
  onServe,
  onFinish,
  onNx = () => {},
}) {
  if (stage !== 1 && stage !== 2 && stage !== 3 && stage !== 4 && stage !== 5 && stage !== 6) {
    throw new Error(`trace: stage must be 1, 2, 3, 4, 5, or 6, got ${stage}`);
  }
  let trace = freshTrace();
  let served = null; // the drained response record, held between hops 4/6 and 5/6

  function freshTrace() {
    return {
      hop: 0,
      method: 'GET',
      path: '/about',
      from: '10.2',
      request: 'GET /about',
      // The request as it travels the wire: identical to `request` except
      // on a hosted Stage 6 path, where the host is resolved away first.
      wireRequest: 'GET /about',
      // The wire request's path part — the cache/db narratives name it.
      wirePath: '/about',
      host: null,
      hostPath: null,
      hostless: false,
      dnsAddress: null,
      dnsStatus: null,
      dnsTarget: null,
      totalHops: null,
      targetServer: null,
      cacheStatus: null,
      dbOp: null,
      dbStale: false,
      response: null,
      status: null,
      body: null,
      routeId: null,
    };
  }

  // The final hop of the current run: a hosted Stage 6 run can shorten when
  // the resolver answers NX, so the machine carries it in the trace state.
  function finalHop() {
    if (trace.totalHops !== null) return trace.totalHops;
    return stage === 5 ? 8 : stage === 4 ? 7 : stage === 3 ? 6 : stage === 2 ? 5 : 4;
  }

  // Serve from the front of the target's queue until the trace's own
  // request (isYou) comes back, or the queue runs dry this tick.
  function drainUntilYou(targetServer) {
    for (;;) {
      const batch = targetServer.step(getTick());
      const you = batch.find((item) => item.isYou);
      if (you || batch.length === 0) return you;
    }
  }

  function backendFor(targetAddress) {
    return servers.find((s) => s.address === targetAddress) ?? servers[0];
  }

  function serve(you) {
    trace.response = you.response;
    trace.status = you.status;
    trace.body = you.body;
    trace.routeId = you.routeId;
    onServe(you);
  }

  // Final hop: the rendered response lands on the browser the trace
  // originated from (the engine routes it into the right browser state).
  function finish(toAddress) {
    onFinish({
      from: trace.from ?? '10.2',
      to: toAddress,
      request: trace.request,
      response: trace.response,
    });
  }

  // Stage 6 split: a hosted path carries a host before the first `/`; a
  // plain path is host-less and replays the Stage 5 machine exactly, so
  // `st` below aliases it to 5.
  function parseStage6Path(path) {
    const slash = path.indexOf('/');
    const host = slash === -1 ? path : path.slice(0, slash);
    const hostPath = slash === -1 ? '/' : path.slice(slash);
    return { host, hostPath };
  }

  return {
    // One hop per call. Returns the hop's lastFrame string, or null when
    // nothing moved (the engine keeps its previous frame then).
    step({ method = 'GET', path = '/about', from = '10.2' } = {}) {
      const final = finalHop();
      const st = stage === 6 && trace.hostless ? 5 : stage;
      let frame = null;
      if (trace.hop === 0 || trace.hop >= final) {
        const request = `${method} ${path}`;
        if (stage === 6) {
          const { host, hostPath } = parseStage6Path(path);
          if (host) {
            // Hosted run start: the browser splits host from path and asks
            // the resolver; 10 hops unless the resolver answers NX (3).
            trace = {
              ...freshTrace(),
              hop: 1,
              method,
              path,
              from,
              request,
              wireRequest: request,
              wirePath: hostPath,
              host,
              hostPath,
              hostless: false,
              dnsAddress: dns ? dns.address : '10.60',
              totalHops: 10,
            };
            frame = `${from} -> ${trace.dnsAddress} | ask ${host}`;
          } else {
            // Host-less run start: byte-identical to the Stage 5 story.
            trace = {
              ...freshTrace(),
              hop: 1,
              method,
              path,
              from,
              request,
              wireRequest: request,
              wirePath: path,
              hostless: true,
              totalHops: 8,
              targetServer: null,
            };
            frame = `${from} -> ${serverAddress} | ${request}`;
          }
        } else {
          trace = {
            ...freshTrace(),
            hop: 1,
            method,
            path,
            from,
            request,
            wireRequest: request,
            wirePath: path,
            targetServer: stage === 1 ? serverAddress : null,
          };
          frame = `${from} -> ${serverAddress} | ${request}`;
        }
        served = null;
      } else if (stage === 6 && !trace.hostless && trace.hop === 1) {
        // Hop 2/10: the resolver answers — a ledger hit inside ttlTicks, an
        // authoritative consult on a miss, or NX for an unknown name. The
        // lookup runs here, against the engine's current tick.
        trace.hop = 2;
        const result = dns.lookup(trace.host, getTick());
        trace.dnsStatus = result.status;
        trace.dnsTarget = result.target;
        if (result.status === 'NX') {
          trace.totalHops = 3;
          frame = `${trace.dnsAddress} -> ${trace.from} | ${trace.host} = NX no record`;
        } else {
          trace.wireRequest = `${trace.method} ${trace.hostPath}`;
          const how = result.status === 'HIT' ? 'cache HIT' : 'authoritative';
          frame = `${trace.dnsAddress} -> ${trace.from} | ${trace.host} = ${result.target} (${how})`;
        }
      } else if (stage === 6 && !trace.hostless && trace.hop === 2 && trace.dnsStatus === 'NX') {
        // Hop 3/3: the browser renders the NX card — the run ends here and
        // no GET is emitted (the LB and queue stay empty).
        trace.hop = 3;
        onNx({ name: trace.host, path: trace.path, from: trace.from, dnsAddress: trace.dnsAddress });
        frame = `Browser ${trace.from} rendered NX no record — no GET emitted (${trace.host} unresolved @ ${trace.dnsAddress})`;
      } else if (stage === 6 && !trace.hostless && trace.hop === 2 && trace.dnsTarget) {
        // Hop 3/10: the browser emits the GET with the resolved target; the
        // host has left the wire request.
        trace.hop = 3;
        frame = `${trace.from} -> ${trace.dnsTarget} | ${trace.wireRequest}`;
      } else if (stage === 6 && !trace.hostless && trace.hop === 3) {
        // Hop 4/10: the network routes the resolved request to the LB.
        trace.hop = 4;
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.wireRequest}) to LoadBalancer`;
      } else if (stage === 6 && !trace.hostless && trace.hop === 4) {
        // Hop 5/10: the LB's round-robin pick enqueues the resolved request.
        trace.hop = 5;
        const atTick = bumpTick();
        const target = lb.enqueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.wireRequest,
          atTick,
          isYou: true,
        });
        trace.targetServer = target;
        frame = `LB ${serverAddress} -> ${target} (${trace.wireRequest}) queued`;
      } else if (stage === 6 && !trace.hostless && trace.hop === 5) {
        // Hop 6/10: the Stage 5 cache/database story — an async POST /jobs
        // enqueues to WorkerQueue 10.40; other requests narrate the db hop
        // they actually took (no phantom async jobs on GET traces, DL-4).
        trace.hop = 6;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          trace.asyncJob = Boolean(served.asyncJob);
          if (served.asyncJob) {
            frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.wirePath})`;
          } else if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.wirePath} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.wirePath} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.wirePath} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if (stage === 6 && !trace.hostless && trace.hop === 6) {
        // Hop 7/10: the webserver answers — an immediate 202 for async jobs,
        // the actually-served response for everything else.
        trace.hop = 7;
        if (served) {
          serve(served);
          frame = served.asyncJob
            ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
            : `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (stage === 6 && !trace.hostless && trace.hop === 7) {
        // Hop 8/10: the network delivers the response.
        trace.hop = 8;
        frame = `Network delivered ${trace.status} response to ${trace.from}`;
      } else if (stage === 6 && !trace.hostless && trace.hop === 8) {
        // Hop 9/10: the browser receives and displays the response.
        trace.hop = 9;
        finish(trace.targetServer ?? serverAddress);
        frame = `Browser ${trace.from} received and displayed ${trace.status}`;
      } else if (stage === 6 && !trace.hostless && trace.hop === 9) {
        // Hop 10/10: an async job tails with the worker's commit; a request
        // served synchronously finds the worker idle.
        trace.hop = 10;
        const dbTarget = database ? database.primaryAddress : '10.30';
        const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
        frame = trace.asyncJob
          ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
          : `Worker ${workerAddr} idle — no async jobs in this trace`;
      } else if (st === 1 && trace.hop === 1) {
        trace.hop = 2;
        const atTick = bumpTick();
        network.deliverToQueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.wireRequest,
          atTick,
          isYou: true,
        });
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.wireRequest}) into queue`;
      } else if (st === 1 && trace.hop === 2) {
        trace.hop = 3;
        const you = drainUntilYou(servers[0]);
        if (you) {
          serve(you);
          frame = `${serverAddress} -> ${trace.from} | ${you.response}`;
        }
      } else if (st === 1 && trace.hop === 3) {
        trace.hop = 4;
        finish(serverAddress);
      } else if (trace.hop === 1) {
        trace.hop = 2;
        frame = `routed ${trace.from} -> ${serverAddress} (${trace.wireRequest}) to LoadBalancer`;
      } else if (trace.hop === 2) {
        trace.hop = 3;
        const atTick = bumpTick();
        const target = lb.enqueue({
          id: `you:${atTick}`,
          from: trace.from,
          to: serverAddress,
          request: trace.wireRequest,
          atTick,
          isYou: true,
        });
        trace.targetServer = target;
        frame = `LB ${serverAddress} -> ${target} (${trace.wireRequest}) queued`;
      } else if (st === 2 && trace.hop === 3) {
        trace.hop = 4;
        const backend = backendFor(trace.targetServer);
        const you = drainUntilYou(backend);
        if (you) {
          serve(you);
          frame = `${backend.address} -> ${trace.from} | ${you.response}`;
        }
      } else if (st === 2 && trace.hop === 4) {
        trace.hop = 5;
        finish(trace.targetServer ?? serverAddress);
      } else if (st === 3 && trace.hop === 3) {
        // Hop 4/6: the target backend checks Cache and serves the queued
        // request; the response record is held one hop so the learner sees
        // the cache lookup before the response leaves the backend.
        trace.hop = 4;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.wirePath})`;
        }
      } else if (st === 3 && trace.hop === 4) {
        trace.hop = 5;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (${trace.cacheStatus})`;
        }
      } else if (st === 3 && trace.hop === 5) {
        trace.hop = 6;
        finish(trace.targetServer ?? serverAddress);
      } else if (st === 4 && trace.hop === 3) {
        // Hop 4/7: the target backend checks Cache and serves the queued
        // request (a POST write-through carries cacheStatus INVALIDATE);
        // the response record is held so the learner watches the cache
        // lookup, then the database hop.
        trace.hop = 4;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          frame = `${backend.address} -> ${cache.address} | cache ${trace.cacheStatus} (${trace.wirePath})`;
        }
      } else if (st === 4 && trace.hop === 4) {
        // Hop 5/7: the database hop — hop 6's WRITE landed on Primary
        // 10.30 (replication queued toward 10.31), hop 5's SELECT read
        // Replica 10.31 fresh or stale, and a warm cache HIT skips the
        // database entirely.
        trace.hop = 5;
        if (served) {
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.wirePath} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.wirePath} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.wirePath} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if (st === 4 && trace.hop === 5) {
        trace.hop = 6;
        if (served) {
          serve(served);
          frame = `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (st === 4 && trace.hop === 6) {
        trace.hop = 7;
        finish(trace.targetServer ?? serverAddress);
      } else if (st === 5 && trace.hop === 3) {
        // Hop 4/8: an async POST /jobs enqueues to WorkerQueue 10.40; other
        // requests narrate the cache/database hop they actually took (the
        // Stage 4 story) — no phantom async jobs on GET traces (DL-4).
        trace.hop = 4;
        const backend = backendFor(trace.targetServer);
        served = drainUntilYou(backend);
        if (served) {
          trace.cacheStatus = served.cacheStatus ?? null;
          trace.dbOp = served.dbOp ?? null;
          trace.dbStale = Boolean(served.dbStale);
          trace.asyncJob = Boolean(served.asyncJob);
          if (served.asyncJob) {
            frame = `${backend.address} -> ${workerQueue ? workerQueue.address : '10.40'} | enqueued async job (${trace.wirePath})`;
          } else if (trace.dbOp === 'WRITE') {
            frame = `Database WRITE ${trace.wirePath} @ ${database.primaryAddress} (replica ${database.replicaAddress} lags ${database.replicationLagTicks}t)`;
          } else if (trace.dbOp === 'SELECT') {
            frame = `Database SELECT ${trace.wirePath} @ ${database.replicaAddress} (${trace.dbStale ? 'STALE' : 'fresh'})`;
          } else {
            frame = `Database SKIP ${trace.wirePath} (warm cache HIT @ ${cache.address})`;
          }
        }
      } else if (st === 5 && trace.hop === 4) {
        // Hop 5/8: the webserver answers — an immediate 202 for async jobs,
        // the actually-served response for everything else.
        trace.hop = 5;
        if (served) {
          serve(served);
          frame = served.asyncJob
            ? `${trace.targetServer} -> ${trace.from} | ${served.response}`
            : `${trace.targetServer} -> ${trace.from} | ${served.response} (cache ${trace.cacheStatus})`;
        }
      } else if (st === 5 && trace.hop === 5) {
        // Hop 6/8: WebServer returns its response via Network
        trace.hop = 6;
        frame = `Network delivered ${trace.status} response to ${trace.from}`;
      } else if (st === 5 && trace.hop === 6) {
        // Hop 7/8: Browser receives and displays the response
        trace.hop = 7;
        finish(trace.targetServer ?? serverAddress);
        frame = `Browser ${trace.from} received and displayed ${trace.status}`;
      } else if (st === 5 && trace.hop === 7) {
        // Hop 8/8: async job tails with the worker's commit; a request that
        // was served synchronously finds the worker idle.
        trace.hop = 8;
        const dbTarget = database ? database.primaryAddress : '10.30';
        const workerAddr = workerQueue ? workerQueue.workerAddress : '10.41';
        frame = trace.asyncJob
          ? `Worker ${workerAddr} finished job and committed to Database ${dbTarget}`
          : `Worker ${workerAddr} idle — no async jobs in this trace`;
      }
      return frame;
    },

    snapshot() {
      return { ...trace };
    },
  };
}

