```js
// One hop-status sentence per hop, in hop order, for each stage's trace
// shape: 4 hops in Stage 1 (emit, route, serve, render), 5 in Stage 2 (LB
// round-robin pick), 6 in Stage 3 (cache check, then response emit), 7 in
// Stage 4 (the database hop after the cache check), 8 in Stage 5, and in
// Stage 6 the hosted shape (10 hops) or the NX shape (3 hops).
function hopSentences(stage, snapshot, from, serverAddress) {
  const t = snapshot.trace ?? {};
  const target = t.targetServer ?? '10.11';
  if (stage === 6 && t.host) {
    // Stage 6 hosted: two DNS hops in front of the Stage 5 chain; the
    // denominator follows the run's live total (10 hosted, 3 on NX).
    const n = t.totalHops ?? 10;
    const dnsAddr = t.dnsAddress ?? '10.60';
    const ask = `Hop 1/${n}: Browser (${from}) asks DNS (${dnsAddr}) for "${t.host}" ("${t.request}")`;
    if (t.dnsStatus === 'NX') {
      return [
        ask,
        `Hop 2/${n}: DNS (${dnsAddr}) -> ${t.host} = NX no record`,
        `Hop 3/${n}: Browser (${from}) rendered NX no record — no GET emitted`,
      ];
    }
    return [
      ask,
      `Hop 2/${n}: DNS (${dnsAddr}) -> ${t.host} = ${t.dnsTarget} (${dnsHow(t.dnsStatus)})`,
      `Hop 3/${n}: Browser (${from}) emits "${t.wireRequest}" to ${t.dnsTarget}`,
      ...stage5Chain(snapshot, t, from, serverAddress, target, n, 2),
    ];
  }
  if (stage >= 5) {
    // Stage 5 and Stage 6 host-less share the 8-hop chain byte-for-byte —
    // a host-less path carries no DNS story.
    return [
      `Hop 1/8: Browser (${from}) emits "${t.request}"`,
      ...stage5Chain(snapshot, t, from, serverAddress, target, 8, 0),
    ];
  }
  if (stage === 4) { ...unchanged... }
  ...
}

// The Stage 5 chain after the emit — hops 2..8 of the 8-hop shape, shifted
// by `shift` hops and read against the `n`-hop denominator for the hosted
// Stage 6 run (the async 202 route and the sync cache/db story alike).
function stage5Chain(snapshot, t, from, serverAddress, target, n, shift) {
  const at = (hop) => hop + shift;
  const worker = snapshot.workerQueue?.workerAddress ?? '10.41';
  const route = `Hop ${at(2)}/${n}: Network (10.x) routes to LoadBalancer (${serverAddress})`;
  const queue = `Hop ${at(3)}/${n}: LoadBalancer (${serverAddress}) -> ${target} queue`;
  const dbOp = dbOpSentence(snapshot, t);
  if (t.asyncJob) {
    return [
      route,
      queue,
      `Hop ${at(4)}/${n}: WebServer (${target}) enqueues job to WorkerQueue (10.40)`,
      `Hop ${at(5)}/${n}: WebServer (${target}) -> "202 Accepted"`,
      `Hop ${at(6)}/${n}: Network delivers 202 response to ${from}`,
      `Hop ${at(7)}/${n}: Browser (${from}) received and displayed 202 Accepted`,
      `Hop ${at(8)}/${n}: Worker (${worker}) processed job and committed to Database (10.30)`,
    ];
  }
  // Requests served synchronously keep the Stage 4 cache/database story;
  // the worker does not see them, so the tail hop reads idle.
  return [
    route,
    queue,
    `Hop ${at(4)}/${n}: ${dbOp}`,
    `Hop ${at(5)}/${n}: WebServer (${target}) -> "${t.response}" (cache ${t.cacheStatus})`,
    `Hop ${at(6)}/${n}: Network delivers ${t.status} response to ${from}`,
    `Hop ${at(7)}/${n}: Browser (${from}) received and displayed ${t.status}`,
    `Hop ${at(8)}/${n}: Worker (${worker}) idle — no async jobs in this trace`,
  ];
}

function dnsHow(status) {
  return status === 'HIT' ? 'cache HIT' : 'authoritative';
}

function dbOpSentence(snapshot, t) {
  const db = snapshot.database ?? {};
  const primary = db.primaryAddress ?? '10.30';
  const replica = db.replicaAddress ?? '10.31';
  const lag = db.replicationLagTicks ?? 3;
  if (t.dbOp === 'WRITE') return `Database WRITE @ Primary (${primary}) — replica lags ${lag}t`;
  if (t.dbOp === 'SELECT' && t.dbStale) return `Database SELECT @ Replica (${replica}) — STALE (lag ${lag}t)`;
  if (t.dbOp === 'SELECT') return `Database SELECT @ Replica (${replica}) — fresh`;
  return `Database SKIP — warm cache HIT (${snapshot.cache?.address ?? '10.20'})`;
}
```

