input.content:
// Stage 6 inspector cards (stage6a brief): the DNS and Router node cards,
// their inspector tabs, and the now-live stage-pill-6 button, built here
// because panel.html sits at its 550-line cap (same split as the teaching
// drawer). All behavior stays addEventListener-only (AGENTS.md CSP rule);
// content is textContent/attributes — no inline styles, no innerHTML.

// CHECKS: ensureStage6Cards is idempotent — panel.js calls it once at boot,
// but a repeat call (e.g. a future hot path) must leave one card set, not
// duplicate the registry.
export function ensureStage6Cards() {
  if (document.getElementById('node-dns')) return;

  document
    .getElementById('stage-pill-5')
    .after(stagePill('6', '6 · Multi-Net / CDN', 'stage-pill-6'));

  const world = document.getElementById('orrery-world');
  world.append(dnsCard(), routerCard());

  const tabs = document.querySelector('.comp-tabs');
  tabs.append(compTab('dns'), compTab('router'));
}

function stagePill(stage, label, testId) {
  const pill = document.createElement('button');
  pill.type = 'button';
  pill.className = 'stage-pill';
  pill.dataset.stage = stage;
  pill.dataset.testid = testId;
  pill.textContent = label;
  return pill;
}

function compTab(name) {
  const tab = document.createElement('button');
  tab.type = 'button';
  tab.className = 'comp-tab';
  tab.dataset.select = name;
  tab.textContent = name;
  return tab;
}

function nodeHead(role, subtitle, chip) {
  const head = document.createElement('header');
  head.className = 'node-head';
  const name = document.createElement('div');
  name.className = 'node-name';
  const roleEl = document.createElement('span');
  roleEl.className = 'role-name';
  roleEl.textContent = role;
  const subEl = document.createElement('span');
  subEl.className = 'node-subtitle';
  subEl.textContent = subtitle;
  const ipChip = document.createElement('span');
  ipChip.className = 'ip-chip';
  ipChip.textContent = chip;
  const codeChip = document.createElement('span');
  codeChip.className = 'code-chip';
  codeChip.textContent = '</> Code';
  name.append(roleEl, subEl);
  head.append(name, ipChip, codeChip);
  return head;
}

function dnsCard() {
  const card = document.createElement('article');
  card.className = 'node-card';
  card.id = 'node-dns';
  card.dataset.testid = 'node-dns';
  card.dataset.component = 'dns';
  card.hidden = true;
  card.append(nodeHead('DNS', 'resolver · tick-TTL ledger', '10.60'));
  const stats = document.createElement('p');
  stats.id = 'dns-stats';
  stats.dataset.testid = 'dns-stats';
  stats.className = 'mono last-frame';
  stats.textContent = 'Lookups: 0 · Cached hits: 0 · TTL: 300t';
  const list = document.createElement('ul');
  list.id = 'dns-entries-list';
  list.dataset.testid = 'dns-entries-list';
  list.className = 'route-list';
  list.setAttribute('aria-label', 'Resolver cache');
  card.append(stats, list);
  return card;
}

function routerCard() {
  const card = document.createElement('article');
  card.className = 'node-card';
  card.id = 'node-router';
  card.dataset.testid = 'node-router';
  card.dataset.component = 'router';
  card.hidden = true;
  card.append(nodeHead('Router', 'cross-subnet forwarding', '10.65 ⇄ 20.1'));
  const stats = document.createElement('p');
  stats.id = 'router-stats';
  stats.dataset.testid = 'router-stats';
  stats.className = 'mono last-frame';
  stats.textContent = 'Routed: 0';
  card.append(stats);
  return card;
}

