import { describe, it, expect } from 'vitest';
import { createDns } from '../../js/sim/dns.js';
import { createEngine } from '../../js/sim/engine.js';

describe('createDns', () => {
  // PINS: both TTL counter-examples from the stage6a brief — a hit inside
  // ttlTicks increments cachedHits with no authoritative consult (the
  // answer's status stays HIT), and an expired entry does not answer from
  // the ledger (the same ask re-consults and reports AUTH).
  it('resolves authoritatively on a miss, serves ledger hits inside ttlTicks, and never answers an expired entry from the ledger', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 5 });

    // Cold ask: the authoritative table answers and the entry warms the
    // ledger (expiresAtTick = 1 + 5 = 6, alive through tick 5).
    expect(dns.lookup('example.com', 1)).toEqual({ status: 'AUTH', name: 'example.com', target: '10.1' });
    expect(dns.snapshot(1).entries).toEqual([
      {
        name: 'example.com',
        target: '10.1',
        cachedAtTick: 1,
        expiresAtTick: 6,
        ttlRemaining: 5,
      },
    ]);

    // Warm ask inside ttlTicks: a ledger HIT — the counters prove the
    // authoritative table was left untouched on this ask.
    expect(dns.lookup('example.com', 5)).toEqual({ status: 'HIT', name: 'example.com', target: '10.1' });
    let snap = dns.snapshot(5);
    expect(snap.lastLookup).toEqual({
      name: 'example.com',
      status: 'HIT',
      target: '10.1',
      atTick: 5,
    });
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 1, authoritative: { 'example.com': '10.1' } });

    // CHECKS: the tick the TTL names is the first tick the entry is gone —
    // the lookup evicts it and re-consults the authoritative table instead
    // of answering the stale ledger row.
    expect(dns.lookup('example.com', 6)).toEqual({ status: 'AUTH', name: 'example.com', target: '10.1' });
    snap = dns.snapshot(6);
    expect(snap).toMatchObject({ lookups: 3, cachedHits: 1 });
    expect(snap.entries).toEqual([
      {
        name: 'example.com',
        target: '10.1',
        cachedAtTick: 6,
        expiresAtTick: 11,
        ttlRemaining: 5,
      },
    ]);

    // CHECKS: the constructor rejects a non-mini-IP address and a
    // non-positive or non-integer ttlTicks (fail-loud over silent misconfig).
    expect(() => createDns({ address: '1060' })).toThrow(/invalid mini-IP/);
    expect(() => createDns({ ttlTicks: 0 })).toThrow(/ttlTicks/);
    expect(() => createDns({ ttlTicks: 2.5 })).toThrow(/ttlTicks/);
  });

  // PINS: the unknown-name branch — NX is an answer, not a throw at the
  // DNS layer; nothing is cached and the counters still count the ask.
  it('answers an unknown name with NX no record and never throws at the DNS layer', () => {
    const dns = createDns({ address: '10.60', ttlTicks: 300 });
    expect(dns.lookup('nope.example', 1)).toEqual({ status: 'NX', name: 'nope.example', target: null });
    expect(dns.lookup('nope.example', 2)).toEqual({ status: 'NX', name: 'nope.example', target: null });
    const snap = dns.snapshot(2);
    expect(snap).toMatchObject({ lookups: 2, cachedHits: 0 });
    expect(snap.entries).toEqual([]);
    expect(snap.lastLookup).toEqual({ name: 'nope.example', status: 'NX', target: null, atTick: 2 });
  });
});

describe('stage 6 engine DNS wiring', () => {
  it('exposes DNS 10.60 on the snapshot and resolves hosted traces through it', () => {
    const engine = createEngine({ stage: 6, dnsTtlTicks: 300 });
    let snap = engine.snapshot();
    expect(snap.dns).not.toBe(null);
    expect(snap.dns.address).toBe('10.60');
    expect(snap.dns.ttlTicks).toBe(300);
    expect(snap.dns.authoritative).toEqual({ 'example.com': '10.1' });
    expect(snap.dns.lookups).toBe(0);

    // The first 2 hops of a hosted trace are the DNS ask and its answer.
    engine.traceHop({ path: 'example.com/about' });
    engine.traceHop({ path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.dns.lookups).toBe(1);
    expect(snap.dns.cachedHits).toBe(0);
    expect(snap.dns.lastLookup).toEqual({
      name: 'example.com',
      status: 'AUTH',
      target: '10.1',
      atTick: 0,
    });
    expect(snap.dns.entries.map((e) => e.name)).toEqual(['example.com']);

    // The second trace's ask is a ledger HIT inside ttlTicks.
    engine.traceHop({ path: 'example.com/about' });
    engine.traceHop({ path: 'example.com/about' });
    snap = engine.snapshot();
    expect(snap.dns).toMatchObject({ lookups: 2, cachedHits: 1 });
    expect(snap.dns.lastLookup.status).toBe('HIT');

    // Stages 1-5 expose no resolver at all.
    expect(createEngine({ stage: 5 }).snapshot().dns).toBe(null);
    expect(createEngine({ stage: 1 }).snapshot().dns).toBe(null);
  });
});

import { describe, it, expect } from 'vitest';
import { createNetwork } from '../../js/sim/network.js';
import { createRouter } from '../../js/sim/router.js';
import { createWebServer } from '../../js/sim/webserver.js';

describe('createRouter', () => {
  // PINS: same-subnet sends keep today's contract byte-for-byte — a
  // registered host answers, an unregistered same-subnet host throws, and
  // with no gateway attached a cross-subnet target throws the same
  // "no server at <addr>" error it always has.
  it('leaves same-subnet sends and queue deliveries unchanged and fails loud without a gateway', () => {
    const net10 = createNetwork();
    net10.registerServer('10.1', createWebServer({ address: '10.1' }));
    expect(net10.send({ from: '10.2', to: '10.1', request: 'GET /about' }).response).toBe(
      '200 This is the about page',
    );
    expect(() => net10.send({ from: '10.2', to: '10.9', request: 'GET /' })).toThrow(
      /no server at 10\.9/,
    );
    // No gateway: a cross-subnet address is just an unregistered host.
    expect(() => net10.send({ from: '10.2', to: '20.1', request: 'GET /' })).toThrow(
      /no server at 20\.1/,
    );
    net10.deliverToQueue({ id: 't:1', from: '10.2', to: '10.1', request: 'GET /', atTick: 1 });
    expect(() =>
      net10.deliverToQueue({ id: 't:2', from: '10.2', to: '20.5', request: 'GET /', atTick: 1 }),
    ).toThrow(/no server at 20\.5/);
  });

  // PINS: a cross-subnet frame takes exactly one router hop — the Router
  // rewrites the source to its interface on the destination subnet,
  // delivers there, and counts the frame once.
  it('forwards a cross-subnet frame through exactly one router hop and rides isYou through', () => {
    const net10 = createNetwork();
    const net20 = createNetwork();
    net10.registerServer('10.1', createWebServer({ address: '10.1' }));
    net20.registerServer('20.5', createWebServer({ address: '20.5' }));
    const router = createRouter({
      leftAddress: '10.65',
      rightAddress: '20.1',
      leftNetwork: net10,
      rightNetwork: net20,
    });
    net10.attachGateway(router);

    const sent = net10.send({ from: '10.2', to: '20.5', request: 'GET /' });
    expect(sent).toEqual({
      from: '10.2',
      to: '20.5',
      request: 'GET /',
      response: '200 Welcome to the home page',
    });
    expect(router.snapshot().routed).toBe(1);
    expect(router.snapshot().lastForward).toEqual({
      from: '20.1', // the Router's 20-side interface carried the frame in
      to: '20.5',
      request: 'GET /',
    });

    // Queue deliveries take the same single hop; isYou rides through to
    // the destination host's queue row.
    net10.deliverToQueue({
      id: 'you:1',
      from: '10.2',
      to: '20.5',
      request: 'GET /about',
      atTick: 1,
      isYou: true,
    });
    expect(router.snapshot().routed).toBe(2);
    const queued = net20.resolve('20.5').queueSnapshot();
    expect(queued).toEqual([
      { id: 'you:1', from: '20.1', to: '20.5', request: 'GET /about', isYou: true },
    ]);

    // A same-subnet send never touches the router.
    net10.send({ from: '10.2', to: '10.1', request: 'GET /' });
    expect(router.snapshot().routed).toBe(2);
  });

  // PINS: the named counter-example — an unregistered 20.x host (20.9)
  // throws the destination network's fail-loud error, and the failed frame
  // leaves the routed counter untouched.
  it('fails loud on an unregistered subnet-20 host (20.9) without counting a routed frame', () => {
    const net10 = createNetwork();
    const net20 = createNetwork();
    const router = createRouter({
      leftNetwork: net10,
      rightNetwork: net20,
    });
    net10.attachGateway(router);
    expect(() => net10.send({ from: '10.2', to: '20.9', request: 'GET /' })).toThrow(
      /no server at 20\.9/,
    );
    expect(() =>
      net10.deliverToQueue({ id: 't:1', from: '10.2', to: '20.9', request: 'GET /', atTick: 1 }),
    ).toThrow(/no server at 20\.9/);
    expect(router.snapshot()).toMatchObject({ routed: 0, lastForward: null });
  });

  it('rejects a non mini-IP interface, a same-subnet pair, or a missing network', () => {
    expect(() => createRouter({ leftAddress: '1065' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ rightAddress: '201' })).toThrow(/invalid mini-IP/);
    expect(() => createRouter({ leftAddress: '10.65', rightAddress: '10.1' })).toThrow(
      /distinct subnets/,
    );
    const router = createRouter({ leftAddress: '10.65', rightAddress: '20.1' });
    expect(() => router.attachNetworks({ left: createNetwork(), right: null })).toThrow(
      /two distinct networks/,
    );
  });
});

